contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, bool freeze) public payable {
        require(true);

        uint256 balBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool frozenBefore = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        c.freezeAccount(target, freeze); if (__ESBMC_reverted()) return;

        assert(c.frozenAccount(target) == freeze && c.balanceOf(target) == balBefore && c.totalSupply() == totalBefore);
    }

    receive() external payable {}
}

