pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, bool freeze) internal {
        vm.assume(true);
        uint256 balBefore;
        try c.balanceOf(target) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 totalBefore;
        try c.totalSupply() returns (uint256 __r) { totalBefore = __r; } catch { return; }
        bool frozenBefore;
        try c.frozenAccount(target) returns (bool __r) { frozenBefore = __r; } catch { return; }
        try c.freezeAccount(target, freeze) {} catch { return; }
        assertTrue(c.frozenAccount(target) == freeze && c.balanceOf(target) == balBefore && c.totalSupply() == totalBefore);
    }

    function testFuzz_run(address target, bool freeze) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, freeze);
    }

    receive() external payable {}
}
